      const cw2 = [0.27, 0.17, 0.17, 0.22, 0.17], xs = []; let cx = L; cw2.forEach(f => { xs.push(cx); cx += CW * f; });
      p.rect(L, y, CW, rh, { fill: PC.deep, r: 6 });
