      const rows = M.outCats.map((r, i) => [String(i + 1), r.label, fmtRp(r.v), fmtPct(r.pct)]), foot = ['', 'Total', fmtRp(M.tout), fmtPct(100)];
      ensure(40 + rh * Math.min(rows.length + 2, 5));
