        const left = rows.length - i, fitsAll = left + 1 <= room, take = fitsAll ? left : Math.min(room, left <= room ? left - 1 : room);
        table(p, L, y, CW, cols, rows.slice(i, i + take), fitsAll ? [foot] : null, rh);
