const BK_LS = 'catatuang.bk.', BK_EPOCH = '1970-01-01T00:00:00.000Z';
const bkCfg = b => { const n = Number(b && b.seconds); return { on: !(b && b.on === false), seconds: Number.isInteger(n) && n >= 5 && n <= 600 ? n : 30 }; };
