  const ts = when && !isNaN(when.getTime()) ? when.getDate() + ' ' + MONTHS_S[when.getMonth()] + ' ' + when.getFullYear() + ', ' + pad(when.getHours()) + ':' + pad(when.getMinutes()) : '-';
