/* ================= Submenu (tertutup secara awal supaya tidak memakan ruang) ================= */
const SUB_KEEP = { master: 'saku.master.v1' };   /* submenu yang pilihannya diingat di perangkat ini; bawaannya terbuka */
function subOpen(k) {
  const st = S.sub || (S.sub = {});
  if (st[k] === undefined) {
    if (SUB_KEEP[k]) { let v = '1'; try { v = localStorage.getItem(SUB_KEEP[k]) || '1'; } catch (e) { /* abaikan */ } st[k] = v !== '0'; }
    else { const m = me(); if (k === 'pw' && m && m.isDefault) st[k] = true; else return false; } /* dibuka otomatis bila masih memakai kata sandi awal, lalu tetap terbuka */
  }
  return !!st[k];
}
function aboutHTML() {
  const f = [['mic', 'Catat cepat', 'Ketik atau ucapkan pengeluaran, kategori dipilihkan.'], ['wallet', 'Rekening', 'Pisahkan saldo bank, e-wallet, dan tunai.'], ['target', 'Anggaran dan target', 'Atur batas belanja dan kejar tujuan tabungan.'], ['chart', 'Laporan dan analisis', 'Grafik arus kas, kategori, dan tren bulanan.'], ['star', 'Tanya SaKu', 'Asisten yang menjawab soal uang Anda.'], ['bell', 'Pengingat', 'Tagihan, cicilan, dan utang tidak terlewat.']];
  const p = [['lock', 'Data milik Anda', 'Cadangkan atau pindahkan kapan saja lewat Cadangan Data.'], ['check', 'Sederhana', 'Satu buku kas, tanpa istilah rumit.'], ['shield', 'Aman', 'Kata sandi dan keluar otomatis menjaga akun Anda.']];
  const tile = x => `<li class="ab-t"><span class="ab-i" aria-hidden="true">${ic(x[0], 20)}</span><b>${x[1]}</b><small>${x[2]}</small></li>`;
  return `<div class="ab"><div class="ab-hero"><span class="ab-logo" aria-hidden="true">${ic('wallet', 26)}</span><div><b class="ab-n">SaKu</b><small>Semua uang ada di SaKu.</small></div><span class="ab-v" translate="no">v${esc(APP_VERSION)}</span></div>
    <p class="ab-p">Buku kas pribadi yang rapi: catat, atur, dan pantau uang Anda dari HP maupun laptop.</p>
    <h3 class="ver-h">Yang bisa Anda lakukan</h3><ul class="ab-g">${f.map(tile).join('')}</ul>
    <h3 class="ver-h">Prinsip SaKu</h3><ul class="ab-g ab-g3">${p.map(tile).join('')}</ul>
    <p class="ab-help">Ada masukan atau kendala? Hubungi administrator SaKu yang membuat akun Anda.</p></div>`;
}
function aboutLog() { const n = CHANGELOG.length; return n > 4 ? CHANGELOG.slice(0, 3).concat([CHANGELOG[n - 1]]) : CHANGELOG; }
function dtMoreClose() { $$('.dt-more-wrap.open').forEach(w => { w.classList.remove('open'); const b = w.querySelector('.dt-more-b'); if (b) b.setAttribute('aria-expanded', 'false'); }); }
function verBodyHTML() {
  const upd = typeof updNative === 'function' && updNative() ? `<div class="btn-row ver-act"><button type="button" class="btn btn-ghost btn-sm" data-act="upd-check">${ic('download', 16)} Cek pembaruan</button></div>` : '';
  return `${upd}${aboutHTML()}<h3 class="ver-h">Yang baru</h3><ol class="ver-list">` + aboutLog().map((c, i) => `<li class="ver-item"><div class="ver-top"><b class="ver-v" translate="no">v${esc(c.v)}</b><span class="ver-d" translate="no">${esc(fmtDateLong(parseYmd(c.d)))}</span>${i === 0 ? '<span class="ver-now">Versi ini</span>' : ''}${i === 3 && CHANGELOG.length > 4 ? '<span class="ver-now">Rilis pertama</span>' : ''}</div><ul class="ver-notes">${c.items.map(x => `<li>${esc(x)}</li>`).join('')}</ul></li>`).join('') + '</ol>';
}
function subMenu(k, title, hint, body) {
  const on = subOpen(k);
  return `<section class="card submenu${on ? ' open' : ''}" data-sub="${k}"><h2 class="sub-title"><button type="button" class="sub-h" data-act="sub" data-k="${k}" aria-expanded="${on}" aria-controls="sub-${k}"><span class="sub-tx"><span class="sub-name">${esc(title)}</span><small id="sub-hint-${k}">${esc(hint)}</small></span><span class="sub-chev">${ic('chevd', 20)}</span></button></h2><div class="sub-body" id="sub-${k}"${on ? '' : ' hidden'}>${body}</div></section>`;
}
function paintSub() {
  $$('#view .submenu').forEach(s => {
    const k = s.dataset.sub, on = subOpen(k), b = s.querySelector('.sub-h'), body = s.querySelector('.sub-body');
    s.classList.toggle('open', on); if (b) b.setAttribute('aria-expanded', String(on)); if (body) body.hidden = !on;
  });
}
function openSub(k) { (S.sub || (S.sub = {}))[k] = true; paintSub(); }

