    $('#pf-user').textContent = 'Nama masuk: ' + m.id + ' · ' + roleName(m.role);
    const ph = $('#sub-hint-pw'); if (ph) ph.textContent = m.isDefault ? 'Anda masih memakai kata sandi awal' : 'Ubah kata sandi akun Anda';
    paintProfile(); paintAvatars();
